def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    base=Counter(x for row in grid for x in row).most_common(1)[0][0]
    edge=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=base and (r in (0,h-1) or c in (0,w-1))]
    bar=Counter(grid[r][c] for r,c in edge).most_common(1)[0][0]
    marks=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=base and grid[r][c]!=bar]
    fill=grid[marks[0][0]][marks[0][1]]
    out=[row[:] for row in grid]
    top=[c for c in range(w) if grid[0][c]==bar]
    bottom=[c for c in range(w) if grid[h-1][c]==bar]
    left=[r for r in range(h) if grid[r][0]==bar]
    right=[r for r in range(h) if grid[r][w-1]==bar]
    if top or bottom:
        cols=set(top+bottom)
        for c in cols:
            for r in range(h):
                if grid[r][c]==base: out[r][c]=fill
    if left or right:
        rows=set(left+right)
        for r in rows:
            for c in range(w):
                if grid[r][c]==base: out[r][c]=fill
    # The two edge groups of the same color define the bounded region.
    if top and bottom:
        lo=min(top); hi=max(bottom)
        if hi < lo: lo,hi=hi,lo
        for r in range(h):
            for c in range(lo,hi+1):
                if grid[r][c]==base: out[r][c]=fill
    if left and right:
        lo=min(left); hi=max(right)
        if hi < lo: lo,hi=hi,lo
        for r in range(lo,hi+1):
            for c in range(w):
                if grid[r][c]==base: out[r][c]=fill
    for r,c in marks: out[r][c]=4
    return out

